CREATE TABLE IF NOT EXISTS bookings (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id TEXT NOT NULL, service_id UUID NOT NULL REFERENCES services(id), address TEXT NOT NULL, scheduled_at TIMESTAMPTZ NOT NULL, status TEXT NOT NULL DEFAULT 'pending', price NUMERIC(10,2) NOT NULL DEFAULT 0, notes TEXT NOT NULL DEFAULT '', provider_name TEXT, eta_minutes INTEGER, created_at TIMESTAMPTZ NOT NULL DEFAULT now());